  const D=s=>s?parseYmd(s):null;rows.forEach(r=>aoa.push([r.id.replace(/^C/,'С'),r.tp||'',r.bld?'Буд '+r.bld:'',r.tenant||'',D(r.start),r.tenant?(r.status||'Зайнято'):(r.status||''),r.note||'',r.card?Number(r.card)||r.card:'',D(r.cardDate),'',r.act||'']));
  aoa.push([]);(d.extra||[]).forEach(x=>aoa.push(['',x.name,'','№ картки '+x.card]));
  const ws=X.utils.aoa_to_sheet(aoa,{cellDates:true,dateNF:'dd\\.mm\\.yyyy'});Object.keys(ws).forEach(k=>{if(ws[k]&&ws[k].t==='d')ws[k].z='dd\\.mm\\.yyyy';});ws['!cols']=[{wch:8},{wch:14},{wch:9},{wch:28},{wch:14},{wch:12},{wch:28},{wch:13},{wch:14},{wch:3},{wch:14}];
